--
-- Name: audit_row_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_row_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Skip no-op UPDATEs (same row written back) to keep the journal signal.
    IF to_jsonb(OLD) = to_jsonb(NEW) THEN RETURN NEW; END IF;
    INSERT INTO audit_row_changes (table_name, row_id, op, old_row, new_row)
    VALUES (TG_TABLE_NAME, (to_jsonb(OLD)->>'id')::uuid, 'UPDATE', to_jsonb(OLD), to_jsonb(NEW));
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO audit_row_changes (table_name, row_id, op, old_row, new_row)
    VALUES (TG_TABLE_NAME, (to_jsonb(OLD)->>'id')::uuid, 'DELETE', to_jsonb(OLD), NULL);
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: audit_row_change_redacted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_row_change_redacted() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  redact text[] := ARRAY[
    'password_hash', 'totp_secret', 'reset_token', 'email_verify_token',
    'tenant_invite_token', 'landlord_invite_token'
  ];
  old_j jsonb; new_j jsonb;
BEGIN
  old_j := to_jsonb(OLD) - redact;
  IF TG_OP = 'UPDATE' THEN
    new_j := to_jsonb(NEW) - redact;
    IF old_j = new_j THEN RETURN NEW; END IF;  -- secret-only change: skip
    INSERT INTO audit_row_changes (table_name, row_id, op, old_row, new_row)
    VALUES (TG_TABLE_NAME, (to_jsonb(OLD)->>'id')::uuid, 'UPDATE', old_j, new_j);
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO audit_row_changes (table_name, row_id, op, old_row, new_row)
    VALUES (TG_TABLE_NAME, (to_jsonb(OLD)->>'id')::uuid, 'DELETE', old_j, NULL);
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: enforce_subtype_pricing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_subtype_pricing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE s RECORD;
BEGIN
  IF NEW.subtype_id IS NULL OR NEW.retired_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT rent_amount, security_deposit, nightly_rate, weekly_rate, monthly_rate
    INTO s FROM property_unit_subtypes WHERE id = NEW.subtype_id;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  -- rent_amount is NOT NULL on units: a class with no rent set leaves the unit's
  -- own number rather than failing the write.
  NEW.rent_amount      := COALESCE(s.rent_amount, NEW.rent_amount);
  NEW.security_deposit := COALESCE(s.security_deposit, 0);
  NEW.nightly_rate     := s.nightly_rate;
  NEW.weekly_rate      := s.weekly_rate;
  NEW.monthly_rate     := s.monthly_rate;
  RETURN NEW;
END;
$$;


--
-- Name: fn_invoice_late_fee_subtotal_rollup_single(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_late_fee_subtotal_rollup_single(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE invoices
  SET subtotal_late_fees = COALESCE((
    SELECT SUM(amount)
    FROM payments
    WHERE invoice_id = p_invoice_id
      AND type = 'late_fee'
      AND status IN ('pending', 'processing', 'settled')
  ), 0)
  WHERE id = p_invoice_id;
END;
$$;


--
-- Name: fn_invoice_late_fee_subtotal_rollup_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_late_fee_subtotal_rollup_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.type = 'late_fee' AND NEW.invoice_id IS NOT NULL THEN
      PERFORM fn_invoice_late_fee_subtotal_rollup_single(NEW.invoice_id);
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.type = 'late_fee' AND OLD.invoice_id IS NOT NULL THEN
      PERFORM fn_invoice_late_fee_subtotal_rollup_single(OLD.invoice_id);
    END IF;
    IF NEW.type = 'late_fee' AND NEW.invoice_id IS NOT NULL
       AND (OLD.type IS DISTINCT FROM 'late_fee'
            OR OLD.invoice_id IS DISTINCT FROM NEW.invoice_id) THEN
      PERFORM fn_invoice_late_fee_subtotal_rollup_single(NEW.invoice_id);
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.type = 'late_fee' AND OLD.invoice_id IS NOT NULL THEN
      PERFORM fn_invoice_late_fee_subtotal_rollup_single(OLD.invoice_id);
    END IF;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: fn_invoice_status_rollup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_status_rollup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (TG_OP = 'DELETE') THEN
    IF OLD.invoice_id IS NOT NULL THEN
      PERFORM fn_invoice_status_rollup_single(OLD.invoice_id);
    END IF;
    RETURN OLD;
  END IF;

  IF (TG_OP = 'UPDATE' AND OLD.invoice_id IS DISTINCT FROM NEW.invoice_id
      AND OLD.invoice_id IS NOT NULL) THEN
    PERFORM fn_invoice_status_rollup_single(OLD.invoice_id);
  END IF;

  IF NEW.invoice_id IS NOT NULL THEN
    PERFORM fn_invoice_status_rollup_single(NEW.invoice_id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_invoice_status_rollup_single(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_status_rollup_single(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_total_children   INTEGER;
  v_settled_children INTEGER;
  v_current_status   TEXT;
  v_new_status       TEXT;
BEGIN
  SELECT status INTO v_current_status FROM invoices WHERE id = p_invoice_id;
  IF v_current_status = 'void' THEN
    RETURN;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'settled')
  INTO v_total_children, v_settled_children
  FROM payments
  WHERE invoice_id = p_invoice_id;

  IF v_total_children = 0 THEN
    v_new_status := 'pending';
  ELSIF v_settled_children = 0 THEN
    v_new_status := 'pending';
  ELSIF v_settled_children = v_total_children THEN
    v_new_status := 'settled';
  ELSE
    v_new_status := 'partial';
  END IF;

  IF v_new_status IS DISTINCT FROM v_current_status THEN
    UPDATE invoices
    SET status = v_new_status, updated_at = now()
    WHERE id = p_invoice_id;
  END IF;
END;
$$;


