--
-- Name: fn_pos_items_log_price_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_pos_items_log_price_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  actor_id uuid;
BEGIN
  IF NEW.sell_price IS DISTINCT FROM OLD.sell_price
     OR NEW.cost_price IS DISTINCT FROM OLD.cost_price THEN
    -- Read actor from session GUC if set by the route layer; ignore
    -- error if unset (direct SQL writes log with NULL changed_by).
    BEGIN
      actor_id := current_setting('gam.user_id', true)::uuid;
    EXCEPTION WHEN OTHERS THEN
      actor_id := NULL;
    END;

    INSERT INTO pos_price_history
      (item_id, old_price, new_price, old_cost, new_cost, changed_by)
    VALUES
      (NEW.id, OLD.sell_price, NEW.sell_price, OLD.cost_price, NEW.cost_price, actor_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: propagate_subtype_pricing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propagate_subtype_pricing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.rent_amount      IS DISTINCT FROM OLD.rent_amount
  OR NEW.security_deposit IS DISTINCT FROM OLD.security_deposit
  OR NEW.nightly_rate     IS DISTINCT FROM OLD.nightly_rate
  OR NEW.weekly_rate      IS DISTINCT FROM OLD.weekly_rate
  OR NEW.monthly_rate     IS DISTINCT FROM OLD.monthly_rate THEN
    UPDATE units u SET
      -- rent_amount is NOT NULL on units; a class that clears its rent leaves
      -- the last known number rather than failing the landlord's save.
      rent_amount      = COALESCE(NEW.rent_amount, u.rent_amount),
      security_deposit = COALESCE(NEW.security_deposit, 0),
      nightly_rate     = NEW.nightly_rate,
      weekly_rate      = NEW.weekly_rate,
      monthly_rate     = NEW.monthly_rate,
      updated_at       = NOW()
     WHERE u.subtype_id = NEW.id AND u.retired_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reject_booking_on_retired_unit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_booking_on_retired_unit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  u_retired timestamptz;
  u_number  text;
BEGIN
  IF NEW.status = 'cancelled' THEN
    RETURN NEW;
  END IF;
  SELECT u.retired_at, u.unit_number INTO u_retired, u_number
    FROM units u WHERE u.id = NEW.unit_id;
  IF u_retired IS NOT NULL THEN
    RAISE EXCEPTION 'Unit % ("%") is retired and cannot take a booking. Use its replacement unit instead.', NEW.unit_id, u_number
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reject_lease_on_unavailable_unit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_lease_on_unavailable_unit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  u_status  text;
  u_retired timestamptz;
  u_number  text;
BEGIN
  IF NEW.status NOT IN ('active', 'pending') THEN
    RETURN NEW;
  END IF;
  SELECT u.status, u.retired_at, u.unit_number
    INTO u_status, u_retired, u_number
    FROM units u WHERE u.id = NEW.unit_id;

  IF u_retired IS NOT NULL THEN
    RAISE EXCEPTION 'Unit % ("%") is retired and cannot hold a lease. Use its replacement unit instead.', NEW.unit_id, u_number
      USING ERRCODE = 'check_violation';
  END IF;
  IF u_status = 'owner_use' THEN
    RAISE EXCEPTION 'Unit % is marked owner-occupied and cannot hold a lease. Change its status first.', NEW.unit_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


