    used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    first_clicked_at timestamp with time zone,
    click_count integer DEFAULT 0 NOT NULL
);


--
-- Name: TABLE landlord_onboarding_booking_tokens; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_onboarding_booking_tokens IS 'S605: opaque prefill credential for the onboarding-call booking link in the post-signup outreach email. Trades server-side for the landlord''s own name/email so the form does not re-ask. Not single-use — expiry is the bound, so a reschedule from the same email still works.';


--
-- Name: COLUMN landlord_onboarding_booking_tokens.first_clicked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_onboarding_booking_tokens.first_clicked_at IS 'S605: when the landlord first opened the booking link from the outreach email. The honest alternative to open-pixel tracking.';


--
-- Name: landlord_other_income; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_other_income (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    property_id uuid,
    unit_id uuid,
    category text NOT NULL,
    amount numeric(12,2) NOT NULL,
    description text,
    payer text,
    income_date date NOT NULL,
    is_common boolean DEFAULT false NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    voided_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT landlord_other_income_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT landlord_other_income_status_check CHECK ((status = ANY (ARRAY['active'::text, 'voided'::text])))
);


--
-- Name: TABLE landlord_other_income; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_other_income IS 'S605: landlord income GAM did not collect (laundry, vending, insurance claims, cash rent deposited). Feeds the P&L income side alongside payments. NEVER holds GAM-collected rent — that would double-count.';


--
-- Name: landlord_platform_fee_overrides; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_platform_fee_overrides (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    landlord_id uuid NOT NULL,
    rate_per_unit numeric(10,2),
    min_per_property numeric(10,2),
    effective_from date DEFAULT CURRENT_DATE NOT NULL,
    effective_until date,
    set_by_user_id uuid,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    str_fee_pct numeric(5,4),
    CONSTRAINT landlord_pfo_at_least_one CHECK (((rate_per_unit IS NOT NULL) OR (min_per_property IS NOT NULL))),
    CONSTRAINT landlord_pfo_effective_range CHECK (((effective_until IS NULL) OR (effective_until > effective_from))),
    CONSTRAINT landlord_pfo_min_nonneg CHECK (((min_per_property IS NULL) OR (min_per_property >= (0)::numeric))),
    CONSTRAINT landlord_pfo_rate_nonneg CHECK (((rate_per_unit IS NULL) OR (rate_per_unit >= (0)::numeric)))
);


--
-- Name: landlords; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlords (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    business_name text,
    ein text,
    onboarding_complete boolean DEFAULT false,
    volume_tier text DEFAULT 'standard'::text,
    annual_contract boolean DEFAULT false,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    maint_approval_threshold numeric(10,2) DEFAULT 500 NOT NULL,
    theme_accent text,
    font_style text,
    agreement_signed_at timestamp with time zone,
    agreement_signature text,
    management_type text,
    network_tier text DEFAULT 'tier_2_full'::text NOT NULL,
    default_entry_notice_hours integer DEFAULT 24 NOT NULL,
    default_early_termination_months_rent numeric(5,2),
    otp_rollout_enabled boolean DEFAULT false NOT NULL,
    default_pm_company_id uuid,
    flex_charge_disqualified_until timestamp with time zone,
    flex_charge_disqualified_reason text,
    background_provider text DEFAULT 'checkr'::text NOT NULL,
    default_ach_fee_payer text DEFAULT 'tenant'::text NOT NULL,
    pos_default_margin_pct numeric(5,2),
    deposit_return_approval_threshold numeric(10,2) DEFAULT 500 NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    stripe_connect_account_id text,
    stripe_connect_status_synced_at timestamp with time zone,
    connect_charges_enabled boolean DEFAULT false NOT NULL,
    connect_payouts_enabled boolean DEFAULT false NOT NULL,
    connect_details_submitted boolean DEFAULT false NOT NULL,
    adverse_action_template text,
    is_system boolean DEFAULT false NOT NULL,
    portfolio_manager_id uuid,
    service_manager_id uuid,
    referred_by_user_id uuid,
    reconciliation_until timestamp with time zone,
    stripe_fc_customer_id text,
    billing_starts_at date,
    billing_grace_until date,
    welcome_outreach_sent_at timestamp with time zone,
    books_start_date date,
    CONSTRAINT landlords_background_provider_check CHECK ((background_provider = ANY (ARRAY['mock'::text, 'checkr'::text]))),
    CONSTRAINT landlords_default_ach_fee_payer_check CHECK ((default_ach_fee_payer = ANY (ARRAY['landlord'::text, 'tenant'::text]))),
    CONSTRAINT landlords_network_tier_check CHECK ((network_tier = 'tier_2_full'::text)),
    CONSTRAINT landlords_pos_default_margin_pct_check CHECK (((pos_default_margin_pct IS NULL) OR ((pos_default_margin_pct >= (0)::numeric) AND (pos_default_margin_pct < (100)::numeric)))),
    CONSTRAINT landlords_volume_tier_check CHECK ((volume_tier = ANY (ARRAY['standard'::text, 'growth'::text, 'professional'::text, 'enterprise'::text, 'partner'::text])))
);


--
-- Name: COLUMN landlords.background_provider; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.background_provider IS 'S423: which background-check provider this landlord uses. Default mock; flip to checkr once Checkr is provisioned for the landlord.';


--
-- Name: COLUMN landlords.is_system; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.is_system IS 'S564: true for GAM-owned system entities (e.g. the renter-pool intake shell landlord). Excluded from aggregate landlord counts + revenue reports; not a customer.';


--
-- Name: COLUMN landlords.portfolio_manager_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.portfolio_manager_id IS 'The CLOSING portfolio manager — the rep who won this deal (25¢/occupied unit/mo residual). Set via referral code at signup, a claim, or super_admin assignment. NULL = no closer, that 25¢ accrues to the pot. See service_manager_id for the customer-service half.';


--
-- Name: COLUMN landlords.service_manager_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.service_manager_id IS 'The portfolio manager who handles this landlord''s customer service (25¢/occupied unit/mo). NULL = unstaffed, that 25¢ accrues to the pot. Distinct from portfolio_manager_id, which is the CLOSING manager (the other 25¢).';


--
-- Name: COLUMN landlords.referred_by_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.referred_by_user_id IS 'The referring LANDLORD''s user id (S567). Set when this landlord signed up with another landlord''s referral code. That referrer earns the closing 25¢/occupied unit/mo residual (as a closer); customer service still routes to a PM via service_manager_id. Mutually exclusive with portfolio_manager_id.';


--
-- Name: COLUMN landlords.reconciliation_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.reconciliation_until IS 'S568: end of the landlord''s onboarding reconciliation window. While NOW() < this, the FIRST rent invoice of any of the landlord''s leases may be marked paid off-platform (old-system autopay overlap) fee-free. Default now()+21d at creation; admin-extendable.';


--
-- Name: COLUMN landlords.billing_starts_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.billing_starts_at IS 'First billing cycle (first-of-month) platformFeeAccrual bills this landlord. NULL = in onboarding grace / not yet activated (no platform fee). Set to the current cycle on first settled rent (operating), or to the grace cap by the daily grace-cap cron. See PLATFORM_FEE_GRACE_CYCLES.';


--
-- Name: COLUMN landlords.billing_grace_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.billing_grace_until IS 'Cap cycle (first-of-month) at which platform-fee billing must begin if the landlord never activates. Set at signup to first-of-month(signup) + PLATFORM_FEE_GRACE_CYCLES months; superadmin-overridable for long setups. NULL falls back to created_at + 2 months in the cron.';


--
-- Name: COLUMN landlords.welcome_outreach_sent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.welcome_outreach_sent_at IS 'S605: when the automated post-signup onboarding-call outreach was sent. NULL = not yet sent (or not eligible). Set once, never cleared — the idempotency guard for jobs/landlordWelcomeOutreach.ts.';


--
-- Name: COLUMN landlords.books_start_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_start_date IS 'S605: bank transactions posted before this date are imported but auto-ignored, keeping pre-GAM history out of the review queue and the P&L. NULL = no cutoff.';


