--
-- Name: security_deposit_interest_accruals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.security_deposit_interest_accruals (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    security_deposit_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    accrual_month date NOT NULL,
    state_code text NOT NULL,
    effective_year integer NOT NULL,
    annual_rate_pct numeric(6,4) NOT NULL,
    principal_amount numeric(10,2) NOT NULL,
    days_held integer NOT NULL,
    days_in_month integer NOT NULL,
    interest_amount numeric(10,4) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    unit_type text,
    act_key text,
    rate_source text,
    earned_amount numeric(10,4),
    spread_amount numeric(10,4),
    market_rate_pct numeric(6,4),
    rate_basis text,
    CONSTRAINT sdi_accruals_rate_basis_check CHECK (((rate_basis IS NULL) OR (rate_basis = ANY (ARRAY['fixed'::text, 'lesser_of_actual'::text, 'share_of_actual'::text, 'actual_earned'::text, 'actual_minus_admin'::text, 'index_linked'::text, 'none'::text])))),
    CONSTRAINT sdi_accruals_rate_source_check CHECK (((rate_source IS NULL) OR (rate_source = ANY (ARRAY['statutory'::text, 'landlord_override'::text])))),
    CONSTRAINT security_deposit_interest_accruals_days_held_check CHECK (((days_held >= 0) AND (days_held <= days_in_month))),
    CONSTRAINT security_deposit_interest_accruals_month_check CHECK ((EXTRACT(day FROM accrual_month) = (1)::numeric))
);


--
-- Name: TABLE security_deposit_interest_accruals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.security_deposit_interest_accruals IS 'Per-month, per-deposit interest accrual log. Idempotent via UNIQUE(security_deposit_id, accrual_month). The cumulative sum of interest_amount writes back to security_deposits.interest_accrued.';


--
-- Name: COLUMN security_deposit_interest_accruals.accrual_month; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.accrual_month IS 'First day of the month being accrued for. CHECK constraint enforces day-1.';


--
-- Name: COLUMN security_deposit_interest_accruals.days_held; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.days_held IS 'Number of days during accrual_month the deposit was held. Full month = days_in_month; partial first/last month is computed from collection date / disbursement date.';


--
-- Name: COLUMN security_deposit_interest_accruals.interest_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.interest_amount IS 'OWED: statutory interest credited to the tenant for this month.';


--
-- Name: COLUMN security_deposit_interest_accruals.unit_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.unit_type IS 'S604: units.unit_type at accrual time — the input that selected the rate row. Deposit interest is unit-type specific, not merely state specific.';


--
-- Name: COLUMN security_deposit_interest_accruals.act_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.act_key IS 'S604: state_law_section_texts.act_key of the statute this rate was read from (e.g. mobile_home_park). NULL for landlord overrides and pre-S603 blanket rows.';


--
-- Name: COLUMN security_deposit_interest_accruals.rate_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.rate_source IS 'S604: statutory catalog vs per-landlord override — which source supplied annual_rate_pct.';


--
-- Name: COLUMN security_deposit_interest_accruals.earned_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.earned_amount IS 'S604 EARNED: what this deposit''s principal yielded at the market rate for the same days_held. NULL when no market rate is on file for the month.';


--
-- Name: COLUMN security_deposit_interest_accruals.spread_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.spread_amount IS 'S604: earned_amount − interest_amount. SIGNED — negative means the statute obliges more than the pool earned and GAM funds the difference.';


--
-- Name: COLUMN security_deposit_interest_accruals.market_rate_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.market_rate_pct IS 'S604: the deposit_pool_yield_rates rate in force for the accrual month, stamped so a row stays re-derivable.';


--
-- Name: COLUMN security_deposit_interest_accruals.rate_basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposit_interest_accruals.rate_basis IS 'S604: how annual_rate_pct was applied to produce interest_amount. fixed = flat; lesser_of_actual = MIN(rate, earned); share_of_actual = share of earned. NULL when nothing was owed.';


--
-- Name: security_deposits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.security_deposits (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    unit_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    total_amount numeric(10,2) NOT NULL,
    collected_amount numeric(10,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    flex_deposit_enabled boolean DEFAULT false,
    installment_count integer,
    installment_amount numeric(10,2),
    installments_paid integer DEFAULT 0,
    installments_remaining integer,
    next_installment_date date,
    interest_accrued numeric(10,2) DEFAULT 0,
    disbursed_to_landlord numeric(10,2) DEFAULT 0,
    disbursed_at timestamp with time zone,
    damage_claimed numeric(10,2) DEFAULT 0,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    held_by text NOT NULL,
    flex_deposit_plan_status text,
    gam_advance_amount numeric(10,2) DEFAULT 0,
    portability_status text DEFAULT 'none'::text NOT NULL,
    portability_authorized_at timestamp with time zone,
    portability_authorized_signature text,
    portability_authorized_ip text,
    portability_target_lease_id uuid,
    carried_from_deposit_id uuid,
    balance_due_full_at timestamp with time zone,
    balance_due_total numeric(10,2),
    custody_fee_active boolean DEFAULT true NOT NULL,
    CONSTRAINT security_deposits_held_by_check CHECK ((held_by = ANY (ARRAY['gam_escrow'::text, 'landlord'::text]))),
    CONSTRAINT security_deposits_no_acceleration_chk CHECK (((balance_due_full_at IS NULL) AND (balance_due_total IS NULL))),
    CONSTRAINT security_deposits_no_advance_chk CHECK (((gam_advance_amount IS NULL) OR (gam_advance_amount = (0)::numeric))),
    CONSTRAINT security_deposits_plan_status_check CHECK (((flex_deposit_plan_status IS NULL) OR (flex_deposit_plan_status = ANY (ARRAY['active'::text, 'completed'::text])))),
    CONSTRAINT security_deposits_portability_status_check CHECK ((portability_status = ANY (ARRAY['none'::text, 'pending_auth'::text, 'authorized'::text, 'carried_forward'::text, 'pending_transfer'::text, 'declined'::text]))),
    CONSTRAINT security_deposits_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'funded'::text, 'partial'::text, 'disbursed'::text, 'claimed'::text])))
);


--
-- Name: COLUMN security_deposits.gam_advance_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposits.gam_advance_amount IS 'DEPRECATED S514: the custody model has no GAM advance — the tenant funds their own deposit. Always 0; retained only for historical rows.';


--
-- Name: COLUMN security_deposits.balance_due_full_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposits.balance_due_full_at IS 'DEPRECATED S514: acceleration removed under the custody model (Consumer ToS § 9.1.5). No longer written.';


--
-- Name: COLUMN security_deposits.balance_due_total; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposits.balance_due_total IS 'DEPRECATED S514: acceleration removed under the custody model (Consumer ToS § 9.1.5). No longer written.';


--
-- Name: COLUMN security_deposits.custody_fee_active; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.security_deposits.custody_fee_active IS 'S516: while TRUE the $3/mo FlexDeposit custody fee is billed. Set FALSE when a forwarded deposit is fully funded via a lump top-up or needed no top-up (ToS § 9.1.6).';


